const input = $input.first().json;
const historico = input.historico ? JSON.parse(input.historico) : [];

// Gerar resumo do contexto para o atendente
const ultimas = historico.slice(-6);
const contexto = ultimas.map(m => `${m.sender === 'user' ? 'Cidadão' : 'Bot'}: ${m.content}`).join('\n');

return [{
  json: {
    remotejid: input.remotejid,
    contexto_resumido: contexto || 'Cidadão solicitou atendimento humano diretamente.',
    responder_cidadao: 'Entendido! Vou transferir você para um atendente humano.\n\nAguarde na fila de atendimento.\nVocê será atendido em breve.\n\nNão feche esta conversa.',
    notificar_agente: true,
    prioridade: 'normal'
  }
}];
